'use strict';
const lessons=[{"page": "00-start", "title": "用格子告訴手臂去哪裡"}, {"page": "angles", "title": "用轉過的路程理解弧度"}, {"page": "vectors", "title": "把兩個位置接成一支位移箭頭"}, {"page": "frames", "title": "同一顆螺絲，用兩把尺描述"}, {"page": "rotation-2d", "title": "兩根尺轉了，任何箭頭都跟著算"}, {"page": "rotation-3d", "title": "在空間轉動，先後會改答案"}, {"page": "transforms", "title": "先轉尺，再加原點位置"}, {"page": "chains", "title": "一節一節把工具點送回世界"}, {"page": "forward", "title": "兩支連桿，逐段找到筆尖"}, {"page": "inverse", "title": "同一個目標，可以彎出兩種手臂"}, {"page": "jacobian", "title": "每個關節的小動作，合成筆尖速度"}, {"page": "singularities", "title": "手臂伸直，少掉一種瞬時速度"}, {"page": "trajectory", "title": "同一條路，安排何時加速和停下"}, {"page": "forces", "title": "同一股末端力，兩顆馬達各負責多少"}, {"page": "dynamics", "title": "力矩先改變轉速，再改變角度"}, {"page": "control", "title": "看到偏差，再決定怎麼推"}, {"page": "orientation", "title": "四個數字，記住一次空間轉動"}];
const current=document.body.dataset.page;const nav=document.getElementById('course-nav');if(nav){nav.innerHTML='<details open><summary>17 課學習路線</summary><ol>'+lessons.map((x,i)=>`<li><a href="${x.page}.html" ${x.page===current?'aria-current="page"':''}>${String(i).padStart(2,'0')}　${x.title}</a></li>`).join('')+'</ol></details>';if(matchMedia('(max-width:760px)').matches)nav.querySelector('details').open=false;}

const dictionarySearch=document.getElementById('glossary-search');if(dictionarySearch){const terms=[...document.querySelectorAll('.term')],status=document.getElementById('dictionary-status');const filter=()=>{const query=dictionarySearch.value.normalize('NFKC').toLocaleLowerCase().trim();let visible=0;for(const term of terms){const match=term.textContent.normalize('NFKC').toLocaleLowerCase().includes(query);term.hidden=!match;if(match)visible++;}status.textContent=visible?`顯示 ${visible} 個名詞（共 ${terms.length} 個）`:'找不到符合的名詞；換個字或清空搜尋再試。';};dictionarySearch.addEventListener('input',filter);filter();}
